function sk970_reference_columns(): array { $out=[];try{$q=db()->query("SELECT TABLE_NAME,COLUMN_NAME,DATA_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND DATA_TYPE IN ('varchar','char','text','mediumtext','longtext','json')");foreach($q->fetchAll() as $r){$t=(string)$r['TABLE_NAME'];if(in_array($t,['storage_profiles_v970','storage_routes_v970','storage_objects_v970','storage_jobs_v970'],true))continue;$out[]=[(string)$r['TABLE_NAME'],(string)$r['COLUMN_NAME']];}}catch(Throwable $e){}return $out; }
function sk970_rewrite_refs(string $old,string $new): int { if($old===''||$new==='')return 0;$n=0;foreach(sk970_reference_columns() as [$t,$c]){try{$sql='UPDATE '.sk970_ident($t).' SET '.sk970_ident($c).'=REPLACE('.sk970_ident($c).',?,?) WHERE '.sk970_ident($c).' LIKE ?';$q=db()->prepare($sql);$q->execute([$old,$new,'%'.$old.'%']);$n+=$q->rowCount();}catch(Throwable $e){}}return $n; }
function sk970_migrate_batch(string $category,int $profileId,string $mode,int $limit,int $uid): array { if(!isset(sk970_categories()[$category]))throw new RuntimeException('Invalid category.');if($category==='cache_archive'&&$mode==='move')throw new RuntimeException('Live cache is intentionally not moved remotely. Use copy/archive or clear cache from Maintenance Center.');$p=sk970_profile($profileId,true);if(!$p||empty($p['enabled']))throw new RuntimeException('Choose an enabled storage profile.');$routes=sk970_routes();$prefix=(string)($routes[$category]['path_prefix']??$category);$files=sk970_files($category,max(1,min(100,$limit)));$out=['category'=>$category,'profile'=>$p['name'],'mode'=>$mode,'processed'=>0,'uploaded'=>0,'moved'=>0,'bytes'=>0,'rewritten_rows'=>0,'failed'=>0,'errors'=>[]];foreach($files as $f){$rel=(string)$f['relative'];$checksum=@hash_file('sha256',$f['path'])?:null;try{$exists=false;if(sk970_table_exists('storage_objects_v970')){$q=db()->prepare('SELECT id,status FROM storage_objects_v970 WHERE source_path=? AND source_checksum=? AND profile_id=? LIMIT 1');$q->execute([$rel,$checksum,$profileId]);$exists=(bool)$q->fetch();}if($exists)continue;$r=sk970_upload($p,$category,$rel,$f['path'],$prefix);$out['processed']++;$out['uploaded']++;$out['bytes']+=(int)$f['size'];$public=(string)($r['public_url']??'');$status='copied';if($mode==='move'){if($public==='')throw new RuntimeException('Move requires Public Base URL so database links can be rewritten safely.');$old='/'.ltrim($rel,'/');$out['rewritten_rows']+=sk970_rewrite_refs($old,$public);if(@unlink($f['path'])){$out['moved']++;$status='moved';}else throw new RuntimeException('Remote upload succeeded but local delete failed.');}if(sk970_table_exists('storage_objects_v970')){$q=db()->prepare('INSERT INTO storage_objects_v970(category,profile_id,source_path,source_checksum,remote_key,public_url,size_bytes,status,migrated_by,migrated_at) VALUES(?,?,?,?,?,?,?,?,?,NOW())');$q->execute([$category,$profileId,$rel,$checksum,$r['key'],$public?:null,(int)$f['size'],$status,$uid?:null]);}}catch(Throwable $e){$out['processed']++;$out['failed']++;if(count($out['errors'])<20)$out['errors'][]=$rel.': '.mb_substr($e->getMessage(),0,220);}}sk970_audit('migrate_batch',$out,$uid);return $out; }
function sk970_recent_objects(int $limit=30): array { try{$q=db()->query('SELECT o.*,p.name profile_name,p.driver FROM storage_objects_v970 o LEFT JOIN storage_profiles_v970 p ON p.id=o.profile_id ORDER BY o.id DESC LIMIT '.max(1,min(100,$limit)));return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
